/**
 * The A4 readability numbers (GH-186, spec 2026-09-28 sec 3). Numbers only:
 * every later task imports from here and retypes nothing. Approved at gate
 * G-NUM on 29 Sep.
 *
 * `radiusTiles` is the OUTER edge of the ring core, and it is the CLASS value.
 * The radius a unit actually draws is per TYPE:
 * `max(class value, 1.15 x that type's own hull half-diagonal)`, so no hull
 * pokes out of its ring and no unit inherits another's size. The per-type table
 * is `RADIUS_BY_TYPE`, generated by `cd tools && npx tsx
 * src/perf/unit-footprints.ts` (which prints the literal) and pinned against a
 * fresh measurement by `tools/src/perf/unit-footprints.test.ts`.
 */

export type RingClass = 'foot' | 'light' | 'armour' | 'air';

/** isAir first, then wheeled && isSoft -> light, wheeled -> armour, else foot. */
export function ringClassOf(t: { isAir: boolean; wheeled: boolean; isSoft: boolean }): RingClass {
  if (t.isAir) return 'air';
  if (t.wheeled) return t.isSoft ? 'light' : 'armour';
  return 'foot';
}

/**
 * Render-side class overrides, keyed by unit type id. The sim classes
 * `dozer_d9` as foot (role `engineer` is in its FOOT_ROLES, and
 * `mobility.wheeled` is not authored), so `ringClassOf` alone would give a
 * tracked 1.26-tile hull the rifleman's ring. Sim data is not ours to change
 * (it would move the pathing domain); the ring reads it as what its flags give
 * once it is a vehicle: soft-skinned, so `light`.
 */
export const RING_CLASS_OVERRIDE: Readonly<Record<string, RingClass>> = { dozer_d9: 'light' };

/**
 * GH-346 (the lead, 2 Oct: "bigrings" ships) made the selected ring bigger
 * and bolder: `thicknessTiles` 0.06 -> 0.10, `minThicknessPx` 1.5 -> 2.5,
 * `coreAlpha` 0.9 -> 0.95, `haloAlpha` 0.35 -> 0.5, and the drawn radius x
 * `SELECTED_RING_SCALE`. `radiusTiles` and the generated tables below are
 * still the TYPE's own footprint ring -- the team ring draws at exactly that.
 * Measurements: docs/superpowers/specs/2026-10-02-readability-design.md.
 */
export const SELECTION_RING = {
  radiusTiles: { foot: 0.45, light: 0.55, armour: 0.7, air: 0.35 },
  thicknessTiles: 0.1,
  /** Screen-pixel floor on the thickness (holds at the 0.35 zoom clamp). */
  minThicknessPx: 2.5,
  featherTiles: 0.015,
  coreAlpha: 0.95,
  /** Outside the core only. */
  haloTiles: 0.03,
  /** 0 means off (Q4). */
  haloAlpha: 0.5,
  capacity: 256,
} as const satisfies {
  radiusTiles: Readonly<Record<RingClass, number>>;
  thicknessTiles: number;
  minThicknessPx: number;
  featherTiles: number;
  coreAlpha: number;
  haloTiles: number;
  haloAlpha: number;
  capacity: number;
};

/** The selected ring's radius and ellipse axes are the type's own x this
 *  (GH-346): a foot ring 40.7 -> 50.9 px wide at zoom 1. */
export const SELECTED_RING_SCALE = 1.25;

/**
 * GH-346: the faint TEAM ring under every unselected unit on open ground --
 * the same radius or ellipse its selection ring has at 1x, in team colour,
 * quieter than a selection. Its own `SelectionRingBatch` (+1 draw call while
 * any unit is in view). Capacity covers the GDD's 300 units with margin; a
 * unit past it simply draws no team ring.
 */
export const TEAM_RING = {
  thicknessTiles: 0.05,
  minThicknessPx: 1.5,
  coreAlpha: 0.55,
  haloAlpha: 0.3,
  capacity: 512,
} as const;

/** `frameAlpha` 1.0, not the 0.8 G-NUM approved: at 0.8 the frame read only
 *  as a slightly darker edge on the mock, at 1.0 as a clear outline (G-MOCK,
 *  the lead, 29 Sep: "Frame 1.0"). */
export const HP_BAR = { widthPx: 24, heightPx: 3, framePx: 1, frameAlpha: 1 } as const;

